changeSet.sql:
SET @lookupTypeId = (SELECT lookup_type_id FROM lookup_type WHERE lookup_type_code = 'ACTIVATION_ISSUE_PRIMARY');
UPDATE lookup_type
SET parent_lookup_type_id = @lookupTypeId
WHERE lookup_type_code = 'ACTIVATION_ISSUE_SECONDARY';
SET @lookupTypeId = (SELECT lookup_type_id FROM lookup_type WHERE lookup_type_code = 'ACTIVATION_ISSUE_SECONDARY');
UPDATE lookup_type
SET parent_lookup_type_id = @lookupTypeId
WHERE lookup_type_code = 'ACTIVATION_ISSUE_TERTIARY';
SET @lookupTypeId = (SELECT lookup_type_id FROM lookup_type WHERE lookup_type_code = 'ORDER_TYPE');
UPDATE lookup_type
SET parent_lookup_type_id = @lookupTypeId
WHERE lookup_type_code = 'SUB_ORDER_TYPE';

ALTER TABLE tenant_lookup_value DROP FOREIGN KEY FK_tenant_lookup_value_lookup_value;
DELETE FROM lookup_value WHERE lookup_type_id = (SELECT lookup_type_id FROM lookup_type WHERE lookup_type_code = 'ACTIVATION_ISSUE_TERTIARY');
DELETE FROM lookup_value WHERE lookup_type_id = (SELECT lookup_type_id FROM lookup_type WHERE lookup_type_code = 'ACTIVATION_ISSUE_SECONDARY');
DELETE FROM lookup_value WHERE lookup_type_id = (SELECT lookup_type_id FROM lookup_type WHERE lookup_type_code = 'ACTIVATION_ISSUE_PRIMARY');
DELETE FROM lookup_value WHERE lookup_type_id = (SELECT lookup_type_id FROM lookup_type WHERE lookup_type_code = 'SUB_ORDER_TYPE');

INSERT INTO config_property (config_property_key, config_property_value) values('SMTP_HOSTNAME', 'host');
INSERT INTO config_property (config_property_key, config_property_value) values('SMTP_PORT_NUMBER', 'port');
INSERT INTO config_property (config_property_key, config_property_value) values('SMTP_USERNAME', 'username');
INSERT INTO config_property (config_property_key, config_property_value) values('SMTP_PASSWORD', null);

INSERT INTO company_config_property (company_id, config_property_key, config_property_value, tenant_id)
VALUES (
        (SELECT company_id FROM company WHERE company_name = 'Endeavor' AND company_type = 'Vertek Client'),
        'LOCK_ONE_LOCATION_PER_ORDER', 'True',
        (SELECT tenant_id FROM v_tenant WHERE name = 'Endeavor')
       );

SET @lookupTypeId = (SELECT lookup_type_id FROM lookup_type WHERE lookup_type_code = 'CONTRACT_TERM');
SET @tenantId = (Select tenant_id from v_tenant t where t.name = 'QTO First Tenant');
INSERT INTO lookup_value (lookup_type_id, lookup_display, lookup_value, sort_seq, lookup_value_active, parent_lookup_value_id, tenant_id)
VALUES (@lookupTypeId, '48 Month', '48 Month', 43, TRUE, NULL, @tenantId),
       (@lookupTypeId, '60 Month', '60 Month', 46, TRUE, NULL, @tenantId);
SET @tenantId = (Select tenant_id from v_tenant t where t.name = 'Demo Tenant');
INSERT INTO lookup_value (lookup_type_id, lookup_display, lookup_value, sort_seq, lookup_value_active, Parent_lookup_value_id, tenant_id)
VALUES (@lookupTypeId, '48 Month', '48 Month', 43, TRUE, NULL, @tenantId),
       (@lookupTypeId, '60 Month', '60 Month', 46, TRUE, NULL, @tenantId);
SET @tenantId = (Select tenant_id from v_tenant t where t.name = 'Endeavor');
INSERT INTO lookup_value (lookup_type_id, lookup_display, lookup_value, sort_seq, lookup_value_active, parent_lookup_value_id, tenant_id)
VALUES (@lookupTypeId, '48 Month', '48 Month', 43, TRUE, NULL, @tenantId),
       (@lookupTypeId, '60 Month', '60 Month', 46, TRUE, NULL, @tenantId);
UPDATE lookup_type SET modifiable = FALSE WHERE lookup_type.lookup_type_id = @lookupTypeId;

UPDATE service
SET speed = CONCAT(IFNULL(download_speed, ''), ' / ', IFNULL(upload_speed, ''))
WHERE speed IS NULL;
UPDATE service
SET speed = null
WHERE download_speed IS NULL AND upload_speed IS NULL;

SET @lookupTypeId = (SELECT lookup_type_id FROM lookup_type WHERE lookup_type_code = 'CONTRACT_TERM');
UPDATE lookup_value SET sort_seq = 10 WHERE lookup_type_id = @lookupTypeId AND lookup_value = 'MTM';
UPDATE lookup_value SET sort_seq = 20 WHERE lookup_type_id = @lookupTypeId AND lookup_value = '12 Month';
UPDATE lookup_value SET sort_seq = 30 WHERE lookup_type_id = @lookupTypeId AND lookup_value = '24 Month';
UPDATE lookup_value SET sort_seq = 40 WHERE lookup_type_id = @lookupTypeId AND lookup_value = '36 Month';
UPDATE lookup_value SET sort_seq = 50 WHERE lookup_type_id = @lookupTypeId AND lookup_value = '48 Month';
UPDATE lookup_value SET sort_seq = 60 WHERE lookup_type_id = @lookupTypeId AND lookup_value = '60 Month';
UPDATE lookup_value SET sort_seq = 70 WHERE lookup_type_id = @lookupTypeId AND lookup_value = '72 Month';

set @lookupTypeId = (Select lookup_type_id from qto.lookup_type where lookup_type_code = 'DISPATCH_VENDOR');
set @lookupValue = 'CTS';
INSERT INTO lookup_value (lookup_type_id, lookup_display, lookup_value, sort_seq, lookup_value_active, parent_lookup_value_id, tenant_id)
SELECT @lookupTypeId, @lookupValue, @lookupValue, 5, TRUE, NULL, t.tenant_id from v_tenant t;
UPDATE lookup_type SET modifiable = FALSE WHERE lookup_type.lookup_type_id = @lookupTypeId;
